namespace Dfit.Models;

/// <summary>Reglas de vigencia y acceso independientes del almacenamiento.</summary>
public static class ReglasMembresia
{
    // Conserva la regla existente: dias completos, no meses de calendario.
    // El llamador proporciona el instante para no depender del reloj en las pruebas.
    public static DateTime CalcularFechaFin(DateTime fechaInicio, int duracionDias)
        => fechaInicio.AddDays(duracionDias);

    // Al llegar exactamente a FechaFin la membresia ya no permite acceso.
    public static bool PermiteAcceso(bool activa, DateTime fechaFin, DateTime ahora)
        => activa && fechaFin > ahora;
}

using Google.Cloud.Firestore;
namespace Dfit.Models.Patterns.Strategy
{
    public interface IPaymentStrategy
    {
        decimal CalculateFinalAmount(decimal baseAmount);
    }

    [FirestoreData]
    public class CashStrategy : IPaymentStrategy
    {
        public decimal CalculateFinalAmount(decimal baseAmount)
        {
            return baseAmount; // Efectivo: Sin recargo
        }
    }

    [FirestoreData]
    public class CardStrategy : IPaymentStrategy
    {
        public decimal CalculateFinalAmount(decimal baseAmount)
        {
            return baseAmount * 1.05m; // Tarjeta: 5% de recargo
        }
    }

    [FirestoreData]
    public class PaymentContext
    {
        private const decimal CardThreshold = 100m;
        private IPaymentStrategy? _strategy;

        public void SetStrategy(IPaymentStrategy strategy)
        {
            _strategy = strategy;
        }

        // Regla existente de RegistrarPago: la estrategia se elige por monto.
        public decimal ExecutePaymentForAmount(decimal baseAmount)
        {
            SetStrategy(baseAmount > CardThreshold ? new CardStrategy() : new CashStrategy());
            return ExecutePayment(baseAmount);
        }

        public decimal ExecutePayment(decimal baseAmount)
        {
            _strategy ??= new CashStrategy(); // Default
            return _strategy.CalculateFinalAmount(baseAmount);
        }
    }
}

using System;
using Google.Cloud.Firestore;

namespace Dfit.Models.Patterns.Proxy
{
    public interface IGymAccess
    {
        bool RegistrarAsistencia(string usuarioId);
        string MensajeError { get; }
    }

    public class RealGymAccess : IGymAccess
    {
        private readonly FirestoreDb _db;
        public string MensajeError { get; private set; } = string.Empty;

        public RealGymAccess(FirestoreDb db)
        {
            _db = db;
        }

        public bool RegistrarAsistencia(string usuarioId)
        {
            _db.Collection("Asistencias").AddAsync(new {
                UsuarioId = usuarioId,
                FechaHoraEntrada = DateTime.UtcNow
            }).Wait();
            MensajeError = "Asistencia registrada en Firebase.";
            return true;
        }
    }

    public class GymAccessProxy : IGymAccess
    {
        private readonly RealGymAccess _realAccess;
        private readonly FirestoreDb _db;
        public string MensajeError { get; private set; } = string.Empty;

        public GymAccessProxy(RealGymAccess realAccess, FirestoreDb db)
        {
            _realAccess = realAccess;
            _db = db;
        }

        public bool RegistrarAsistencia(string usuarioId)
        {
            var snap = _db.Collection("MembresiasUsuarios")
                .WhereEqualTo("UsuarioId", usuarioId)
                .WhereEqualTo("Activa", true)
                .GetSnapshotAsync().Result;
                
            bool tieneAcceso = false;
            foreach(var doc in snap.Documents) {
                if (ReglasMembresia.PermiteAcceso(doc.GetValue<bool>("Activa"),
                    doc.GetValue<DateTime>("FechaFin"), DateTime.UtcNow)) {
                    tieneAcceso = true;
                    break;
                }
            }

            if (tieneAcceso)
            {
                bool resultado = _realAccess.RegistrarAsistencia(usuarioId);
                MensajeError = _realAccess.MensajeError;
                return resultado;
            }
            else
            {
                MensajeError = "Acceso denegado: No tienes una membresía activa.";
                return false;
            }
        }
    }
}

